#define _POSIX_C_SOURCE 200809L
#include "cvc_worktree.h"
#include "cvc_object.h"
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/stat.h>

int cvc_worktree_selected(CvcRepo*r,int store,CvcSnapshot*out){return cvc_snapshot_scan(r->root,r->cvc,&r->config,store,out);}
int cvc_worktree_is_clean(CvcRepo*r,const CvcSnapshot*head,CvcSnapshot*work,int*clean){if(cvc_worktree_selected(r,0,work)<0)return -1;*clean=cvc_snapshot_equal(head,work);return 0;}
static int readlink_buf(const char*p,CvcBuf*b){cvc_buf_init(b);size_t cap=128;for(;;){b->data=cvc_xrealloc(b->data,cap);ssize_t n=readlink(p,(char*)b->data,cap);if(n<0){cvc_buf_free(b);return -1;}if((size_t)n<cap){b->len=(size_t)n;b->cap=cap;return 0;}cap*=2;}}
int cvc_worktree_entry(CvcRepo*r,const char*rel,int*exists,uint8_t*type,uint8_t oid[32],int eligible){char*p=cvc_path_join(r->root,rel);struct stat st;if(lstat(p,&st)<0){if(errno==ENOENT||errno==ENOTDIR){*exists=0;free(p);return 0;}int e=errno;free(p);return cvc_errorf("cannot inspect %s: %s",rel,strerror(e));}*exists=1;if(S_ISLNK(st.st_mode)){CvcBuf b;if(readlink_buf(p,&b)<0){free(p);return cvc_errorf("cannot read symlink %s",rel);}*type=2;cvc_object_oid(CVC_OBJ_SYMLINK,b.data,b.len,oid);cvc_buf_free(&b);free(p);return 0;}if(S_ISREG(st.st_mode)){if(eligible&&((uint64_t)st.st_size>CVC_TEXT_MAX)){free(p);return cvc_errorf("ineligible regular file at %s",rel);}int fd=open(p,O_RDONLY|O_CLOEXEC|O_NOFOLLOW);if(fd<0){free(p);return cvc_errorf("cannot open %s",rel);}CvcBuf b;cvc_buf_init(&b);unsigned char buf[32768];for(;;){ssize_t n=read(fd,buf,sizeof(buf));if(n<0&&errno==EINTR)continue;if(n<0){close(fd);cvc_buf_free(&b);free(p);return cvc_errorf("cannot read %s",rel);}if(!n)break;cvc_buf_append(&b,buf,(size_t)n);}close(fd);if(eligible){size_t z=b.len<CVC_PROBE_MAX?b.len:CVC_PROBE_MAX;if(b.len>CVC_TEXT_MAX||memchr(b.data,0,z)){cvc_buf_free(&b);free(p);return cvc_errorf("ineligible regular file at %s",rel);}}*type=1;cvc_object_oid(CVC_OBJ_BLOB,b.data,b.len,oid);cvc_buf_free(&b);free(p);return 0;}*type=S_ISDIR(st.st_mode)?3:0;memset(oid,0,32);free(p);return 0;}
static int under_root(const char*root,const char*p){size_t n=strlen(root);return !strncmp(root,p,n)&&(p[n]=='/'||p[n]==0);}
static int path_under_any(const CvcStrVec*v,const char*p){for(size_t i=0;i<v->n;i++){size_t n=strlen(v->v[i]);if(!strcmp(v->v[i],p)||(!strncmp(v->v[i],p,n)&&p[n]=='/'))return 1;}return 0;}
static int current_has_prefix_leaf(const CvcSnapshot*c,const char*p){size_t n=strlen(p);for(size_t i=0;i<c->n;i++)if(!strncmp(c->v[i].path,p,n)&&c->v[i].path[n]=='/')return 1;return 0;}
static int current_exact(const CvcSnapshot*c,const char*p){return cvc_snapshot_find(c,p)>=0;}
static int dir_empty_local(const char*p){DIR*d=opendir(p);if(!d)return 0;int empty=1;struct dirent*de;while((de=readdir(d)))if(strcmp(de->d_name,".")&&strcmp(de->d_name,"..")){empty=0;break;}closedir(d);return empty;}
static int extra_owns(const CvcStrVec*extra,const char*path);
static int dir_contains_untracked_rec(CvcRepo*r,const char*abs,const char*rel,const CvcSnapshot*cur,int*yes){DIR*d=opendir(abs);if(!d)return -1;struct dirent*de;while((de=readdir(d))){if(!strcmp(de->d_name,".")||!strcmp(de->d_name,".."))continue;char*rp=rel[0]?cvc_path_join(rel,de->d_name):cvc_xstrdup(de->d_name);char*ap=cvc_path_join(abs,de->d_name);struct stat st;if(lstat(ap,&st)<0){free(rp);free(ap);closedir(d);return -1;}if(S_ISDIR(st.st_mode)){if(dir_contains_untracked_rec(r,ap,rp,cur,yes)<0){free(rp);free(ap);closedir(d);return -1;}if(*yes){free(rp);free(ap);closedir(d);return 0;}}else if(!current_exact(cur,rp)){*yes=1;free(rp);free(ap);closedir(d);return 0;}free(rp);free(ap);}closedir(d);return 0;}
static int ensure_parents_safe(CvcRepo*r,const char*rel,const CvcSnapshot*cur,const CvcStrVec*extra){
    char *copy=cvc_xstrdup(rel);
    for(char *p=copy; *p; p++){
        if(*p!='/') continue;
        *p=0;
        char *rp=cvc_xstrdup(copy);
        char *ap=cvc_path_join(r->root,rp);
        struct stat st;
        if(lstat(ap,&st)==0){
            if(!S_ISDIR(st.st_mode) && !current_exact(cur,rp) && !(extra_owns(extra,rp)&&current_has_prefix_leaf(cur,rp))){
                int rr=cvc_errorf("untracked collision at %s",rp);
                free(ap);free(rp);free(copy);return rr;
            }
        }else if(errno!=ENOENT && errno!=ENOTDIR){
            int e=errno; free(ap);free(rp);free(copy);
            return cvc_errorf("cannot inspect parent path: %s",strerror(e));
        }
        free(ap);free(rp);*p='/';
    }
    free(copy);return 0;
}
static int snap_same_entry(const CvcSnapshot*a,size_t i,const CvcSnapshot*b);
static int extra_owns(const CvcStrVec*extra,const char*path){if(!extra)return 0;for(size_t i=0;i<extra->n;i++){size_t n=strlen(extra->v[i]);if(!strcmp(path,extra->v[i])||(!strncmp(path,extra->v[i],n)&&path[n]=='/'))return 1;}return 0;}
static int snap_has_descendant(const CvcSnapshot*s,const char*root){size_t n=strlen(root);for(size_t i=0;i<s->n;i++)if(!strncmp(s->v[i].path,root,n)&&s->v[i].path[n]=='/')return 1;return 0;}
static int preflight(CvcRepo*r,const CvcSnapshot*cur,const CvcSnapshot*target,const CvcStrVec*extra){for(size_t i=0;i<target->n;i++){if(snap_same_entry(target,i,cur)&&!extra_owns(extra,target->v[i].path))continue;const char*p=target->v[i].path;if(ensure_parents_safe(r,p,cur,extra)<0)return -1;char*ap=cvc_path_join(r->root,p);struct stat st;if(lstat(ap,&st)==0){ssize_t ci=cvc_snapshot_find(cur,p);if(ci>=0){if(S_ISDIR(st.st_mode)){int un=0;if(dir_contains_untracked_rec(r,ap,p,cur,&un)<0){free(ap);return cvc_errorf("cannot inspect tracked type-change directory %s",p);}if(un){free(ap);return cvc_errorf("untracked collision beneath %s",p);}}}else if(current_has_prefix_leaf(cur,p)){if(!S_ISDIR(st.st_mode)){free(ap);return cvc_errorf("working tree collision at %s",p);}int un=0;if(dir_contains_untracked_rec(r,ap,p,cur,&un)<0){free(ap);return -1;}if(un){free(ap);return cvc_errorf("untracked collision beneath %s",p);}}else{free(ap);return cvc_errorf("untracked/ineligible collision at %s",p);}}else if(errno!=ENOENT&&errno!=ENOTDIR){int e=errno;free(ap);return cvc_errorf("cannot inspect %s: %s",p,strerror(e));}free(ap);}return 0;}
static int snap_same_entry(const CvcSnapshot*a,size_t i,const CvcSnapshot*b){ssize_t j=cvc_snapshot_find(b,a->v[i].path);return j>=0&&a->v[i].type==b->v[j].type&&!memcmp(a->v[i].oid,b->v[j].oid,32);}
static int mkdir_parent_for(const char*p){char*d=cvc_path_dirname(p);int rc=cvc_mkdir_p(d,0777);free(d);return rc;}
static char*backup_path(const char*bak,const char*rel){return cvc_path_join(bak,rel);}
static int remove_if_exists(const char*p){struct stat st;if(lstat(p,&st)<0)return (errno==ENOENT||errno==ENOTDIR)?0:-1;if(S_ISDIR(st.st_mode))return rmdir(p);return unlink(p);}
/* parent creation variant used after backups; current tracked leaf parents have been moved */
static int create_parent_dirs(CvcRepo*r,const char*rel){char*copy=cvc_xstrdup(rel);for(char*p=copy;*p;p++)if(*p=='/'){*p=0;char*ap=cvc_path_join(r->root,copy);struct stat st;if(lstat(ap,&st)<0){if(errno==ENOENT){if(mkdir(ap,0777)<0){int e=errno;free(ap);free(copy);return cvc_errorf("cannot create parent: %s",strerror(e));}}else{free(ap);free(copy);return -1;}}else if(!S_ISDIR(st.st_mode)){free(ap);free(copy);return cvc_errorf("unsafe non-directory parent");}free(ap);*p='/';}free(copy);return 0;}
static int install_object2(CvcRepo*r,const CvcSnapEntry*e,const char*txn,int*did_install){*did_install=0;CvcObjType t;CvcBuf p;if(cvc_object_read(r->cvc,e->oid,&t,&p)<0)return -1;if((e->type==1&&t!=CVC_OBJ_BLOB)||(e->type==2&&t!=CVC_OBJ_SYMLINK)){cvc_buf_free(&p);return cvc_errorf("object type mismatch for %s",e->path);}if(create_parent_dirs(r,e->path)<0){cvc_buf_free(&p);return -1;}char*dest=cvc_path_join(r->root,e->path);struct stat st;if(lstat(dest,&st)==0&&S_ISDIR(st.st_mode)){if(rmdir(dest)<0){cvc_buf_free(&p);free(dest);return cvc_errorf("cannot replace directory %s",e->path);}}else if(lstat(dest,&st)==0){if(unlink(dest)<0){cvc_buf_free(&p);free(dest);return -1;}}char*stage=cvc_path_join(txn,"stage");if(cvc_mkdir_p(stage,0777)<0){cvc_buf_free(&p);free(dest);free(stage);return -1;}size_t ns=strlen(stage);char*tmp=cvc_xmalloc(ns+32);snprintf(tmp,ns+32,"%s/item-XXXXXX",stage);int rc=0,e0=0;if(e->type==1){int fd=mkstemp(tmp);if(fd<0)rc=-1,e0=errno;else{if(fchmod(fd,0666)<0||cvc_write_all(fd,p.data,p.len)<0||fsync(fd)<0)rc=-1,e0=errno;if(close(fd)<0&&rc==0)rc=-1,e0=errno;if(rc==0&&rename(tmp,dest)<0)rc=-1,e0=errno;else if(rc==0)*did_install=1;if(rc<0)unlink(tmp);}}else{int fd=mkstemp(tmp);if(fd<0)rc=-1,e0=errno;else{close(fd);unlink(tmp);char*target=cvc_xmalloc(p.len+1);memcpy(target,p.data,p.len);target[p.len]=0;if(symlink(target,tmp)<0)rc=-1,e0=errno;else if(rename(tmp,dest)<0){rc=-1;e0=errno;unlink(tmp);}else *did_install=1;free(target);}}if(rc==0&&cvc_fsync_parent(dest)<0)rc=-1,e0=errno;free(tmp);free(stage);free(dest);cvc_buf_free(&p);if(rc<0){errno=e0;return cvc_errorf("failed to materialize %s: %s",e->path,strerror(e0));}return 0;}
static int rm_empty_parents(CvcRepo*r,const char*rel){char*ap=cvc_path_join(r->root,rel);char*d=cvc_path_dirname(ap);while(strcmp(d,r->root)&&under_root(r->root,d)){if(rmdir(d)<0)break;char*u=cvc_path_dirname(d);free(d);d=u;}free(d);free(ap);return 0;}
int cvc_materialize_snapshot_owned(CvcRepo*r,const CvcSnapshot*cur,const CvcSnapshot*target,const CvcStrVec*extra){if(preflight(r,cur,target,extra)<0)return -1;char*state=cvc_path_join(r->cvc,"state");size_t ns=strlen(state);char*txn=cvc_xmalloc(ns+32);snprintf(txn,ns+32,"%s/txn-XXXXXX",state);free(state);if(!mkdtemp(txn)){free(txn);return cvc_errorf("cannot create working-tree transaction");}char*bak=cvc_path_join(txn,"backup");if(mkdir(bak,0777)<0){cvc_remove_tree_nofollow(txn);free(bak);free(txn);return -1;}CvcStrVec moved;cvc_strvec_init(&moved);CvcStrVec installed;cvc_strvec_init(&installed);int rc=0;
/* Move every changed current tracked leaf out of the way. */
for(size_t i=0;i<cur->n&&rc==0;i++){if(snap_same_entry(cur,i,target)&&!extra_owns(extra,cur->v[i].path))continue;char*src=cvc_path_join(r->root,cur->v[i].path);struct stat st;if(lstat(src,&st)<0){if(errno==ENOENT||errno==ENOTDIR){free(src);continue;}free(src);rc=-1;break;}if(S_ISDIR(st.st_mode)&&!dir_empty_local(src)){free(src);rc=cvc_errorf("cannot replace nonempty local directory at %s",cur->v[i].path);break;}char*bp=backup_path(bak,cur->v[i].path);if(mkdir_parent_for(bp)<0||rename(src,bp)<0){free(src);free(bp);rc=cvc_errorf("cannot backup %s during materialization",cur->v[i].path);break;}cvc_strvec_push(&moved,cur->v[i].path);free(src);free(bp);rm_empty_parents(r,cur->v[i].path);}
/* Extra owned roots (merge conflict artifacts) are moved if present and not already moved. */
for(size_t i=0;extra&&i<extra->n&&rc==0;i++){const char*rel=extra->v[i];if(cvc_strvec_contains(&moved,rel))continue;char*src=cvc_path_join(r->root,rel);struct stat st;if(lstat(src,&st)<0){free(src);continue;}if(S_ISDIR(st.st_mode)){/* A structural directory operand is a container, not an owned leaf. Its tracked descendants are already moved individually, while unrelated untracked descendants must survive recursive restore/materialization. */if(cvc_snapshot_find(cur,rel)<0&&cvc_snapshot_find(target,rel)<0&&(snap_has_descendant(cur,rel)||snap_has_descendant(target,rel))){free(src);continue;}/* Otherwise this root itself is an owned conflict artifact; replacing a nonempty unrelated directory would destroy untracked content. */if(!dir_empty_local(src)){free(src);rc=cvc_errorf("abort/materialization collision at conflict root %s",rel);break;}}char*bp=backup_path(bak,rel);if(mkdir_parent_for(bp)<0||rename(src,bp)<0){free(src);free(bp);rc=-1;break;}cvc_strvec_push(&moved,rel);free(src);free(bp);}
for(size_t i=0;i<target->n&&rc==0;i++){if(snap_same_entry(target,i,cur)&&!extra_owns(extra,target->v[i].path))continue;int did_install=0;if(install_object2(r,&target->v[i],txn,&did_install)<0){if(did_install)cvc_strvec_push(&installed,target->v[i].path);rc=-1;break;}cvc_strvec_push(&installed,target->v[i].path);}
if(rc<0){/* remove newly installed leaves, then put exact backups back */for(size_t i=installed.n;i>0;i--){char*p=cvc_path_join(r->root,installed.v[i-1]);remove_if_exists(p);rm_empty_parents(r,installed.v[i-1]);free(p);}for(size_t i=moved.n;i>0;i--){const char*rel=moved.v[i-1];char*bp=backup_path(bak,rel);char*dst=cvc_path_join(r->root,rel);create_parent_dirs(r,rel);remove_if_exists(dst);if(rename(bp,dst)<0)cvc_warnf("failed to restore transaction backup for %s",rel);free(bp);free(dst);}cvc_remove_tree_nofollow(txn);}else if(cvc_remove_tree_nofollow(txn)<0){cvc_warnf("could not remove completed transaction scratch");}
cvc_strvec_free(&moved);cvc_strvec_free(&installed);free(bak);free(txn);return rc;}
int cvc_materialize_snapshot(CvcRepo*r,const CvcSnapshot*c,const CvcSnapshot*t){return cvc_materialize_snapshot_owned(r,c,t,NULL);}
static int ignored_root(const CvcStrVec*v,const char*p){return v&&path_under_any(v,p);}
int cvc_snapshot_actual_matches(CvcRepo*r,const CvcSnapshot*exp,const CvcStrVec*ignore,int*matches,char**bad){*matches=1;if(bad)*bad=NULL;CvcConfig all;cvc_config_init_defaults(&all);CvcSnapshot act;if(cvc_snapshot_scan(r->root,r->cvc,&all,0,&act)<0){cvc_config_free(&all);return -1;}cvc_config_free(&all);for(size_t i=0;i<exp->n;i++){if(ignored_root(ignore,exp->v[i].path))continue;ssize_t j=cvc_snapshot_find(&act,exp->v[i].path);if(j<0||act.v[j].type!=exp->v[i].type||memcmp(act.v[j].oid,exp->v[i].oid,32)){*matches=0;if(bad)*bad=cvc_xstrdup(exp->v[i].path);break;}}if(*matches){for(size_t j=0;j<act.n;j++){if(ignored_root(ignore,act.v[j].path))continue;if(cvc_snapshot_find(exp,act.v[j].path)<0){/* only consider actual path unexpected if it lies in tracked/provisional universe? For strict merge provisional, yes. */*matches=0;if(bad)*bad=cvc_xstrdup(act.v[j].path);break;}}}cvc_snapshot_free(&act);return 0;}
int cvc_write_working_bytes(CvcRepo*r,const char*rel,const unsigned char*data,size_t len){if(!cvc_repo_path_valid(rel))return cvc_errorf("invalid working path");if(create_parent_dirs(r,rel)<0)return -1;char*dest=cvc_path_join(r->root,rel),*dir=cvc_path_dirname(dest);size_t nd=strlen(dir);char*tmp=cvc_xmalloc(nd+32);snprintf(tmp,nd+32,"%s/.cvc-write-XXXXXX",dir);int fd=mkstemp(tmp);int rc=0,e=0;if(fd<0)rc=-1,e=errno;else{if(fchmod(fd,0666)<0||cvc_write_all(fd,data,len)<0||fsync(fd)<0)rc=-1,e=errno;if(close(fd)<0&&rc==0)rc=-1,e=errno;if(rc==0&&rename(tmp,dest)<0)rc=-1,e=errno;if(rc<0)unlink(tmp);}free(tmp);free(dir);free(dest);if(rc<0){errno=e;return cvc_errorf("cannot write conflict file %s",rel);}return 0;}
